2	
3	namespace App\Services\Shopify;
4	
5	use App\Models\Core\Professional\BrandProfile;
6	use App\Models\Core\Professional\Professional;
7	use App\Models\Core\Professional\ProfessionalIntegration;
8	use App\Models\Core\Site\Site;
9	use Illuminate\Support\Arr;
10	
11	// Auto-fills professional, brand profile, and integration fields from Shopify shop data
12	// during OAuth onboarding, and handles on-demand resyncs.
13	//
14	// Resync semantics (Option B — Shopify as source of truth):
15	//   For each Shopify-sourced field, if Shopify returns a non-empty value, the local
16	//   value is overwritten. If Shopify returns empty or omits the field, the local
17	//   value is preserved. Manual edits in Sidest are NOT protected — a brand that
18	//   wants to keep a custom display_name should edit it in Shopify, not locally.
19	class ShopProfileAutoFillService
20	{
21	    /**
22	     * The 12 Shopify → Side St field mappings used by both signup auto-fill and resync.
23	     *
24	     * Each entry:
25	     *   - 'shopify' = key on the shop.json payload
26	     *   - 'target'  = one of 'professional', 'brand_profile', 'integration'
27	     *   - 'column'  = column (or metadata key, for integration target) on the target.
28	     *                  Also used as the logical field name in the resync response.
29	     */
30	    private const FIELD_MAP = [
31	        ['shopify' => 'name', 'target' => 'professional', 'column' => 'display_name'],
32	        ['shopify' => 'email', 'target' => 'professional', 'column' => 'primary_email'],
33	        ['shopify' => 'phone', 'target' => 'professional', 'column' => 'phone'],
34	        ['shopify' => 'address1', 'target' => 'professional', 'column' => 'location_street_address'],
35	        ['shopify' => 'city', 'target' => 'professional', 'column' => 'location_city'],
36	        ['shopify' => 'province', 'target' => 'professional', 'column' => 'location_state'],
37	        ['shopify' => 'zip', 'target' => 'professional', 'column' => 'location_postcode'],
38	        ['shopify' => 'country_name', 'target' => 'professional', 'column' => 'location_country'],
39	        ['shopify' => 'country_code', 'target' => 'professional', 'column' => 'country_code'],
40	        ['shopify' => 'iana_timezone', 'target' => 'professional', 'column' => 'timezone'],
41	        ['shopify' => 'domain', 'target' => 'brand_profile', 'column' => 'business_website'],
42	        ['shopify' => 'currency', 'target' => 'integration', 'column' => 'shop_currency'],
43	    ];
44	
45	    /**
46	     * Fill Professional, Site, and BrandProfile fields from a Shopify shop object (signup path).
47	     * Only fills fields that are currently empty — never overwrites existing values.
48	     *
49	     * @param  array  $shopData  The `shop` object from Shopify's Admin API shop.json response
50	     */
51	    public function fillFromShopData(
52	        Professional $professional,
53	        Site $site,
54	        ?BrandProfile $brandProfile,
55	        array $shopData,
56	        ?ProfessionalIntegration $integration = null,
57	    ): void {
58	        $this->fillProfessional($professional, $shopData);
59	        $this->fillBrandProfile($brandProfile, $shopData);
60	        $this->fillIntegrationCurrency($integration, $shopData);
61	
62	        $professional->save();
63	
64	        if ($brandProfile !== null) {
65	            $brandProfile->save();
66	        }
67	    }
68	
69	    /**
70	     * Resync Shopify-sourced fields. For each field in FIELD_MAP:
71	     *   - If Shopify returns a non-empty value → overwrite local.
72	     *   - If Shopify returns empty/missing → preserve local.
73	     *
74	     * No comparison against prior state; no "manual edit" detection.
75	     *
76	     * @return array{updated: string[], preserved: string[]}
77	     */
78	    public function resyncFromShopData(ProfessionalIntegration $integration, array $shopData): array
79	    {
80	        $professional = Professional::findOrFail($integration->professional_id);
81	        $brandProfile = BrandProfile::where('professional_id', $integration->professional_id)->first();
82	
83	        $updated = [];
84	        $preserved = [];
85	        $professionalDirty = false;
86	        $brandProfileDirty = false;
87	
88	        // Integration-target field writes (currently just shop_currency) go through
89	        // mergeProviderMetadata so sibling keys (webhook ids, storefront tokens, etc.)
90	        // written by concurrent jobs survive this update.
91	        $metadataMerge = [];
92	
93	        foreach (self::FIELD_MAP as $field) {
94	            $freshValue = $this->freshValueForField($field, $shopData);
95	
96	            if ($freshValue === '') {
97	                $preserved[] = $field['column'];
98	
99	                continue;
100	            }
101	
102	            $this->applyFreshValue($field, $freshValue, $professional, $brandProfile, $metadataMerge, $professionalDirty, $brandProfileDirty);
103	            $updated[] = $field['column'];
104	        }
105	
106	        if ($professionalDirty) {
107	            $professional->save();
108	        }
109	        if ($brandProfileDirty && $brandProfile !== null) {
110	            $brandProfile->save();
111	        }
112	
113	        if ($metadataMerge !== []) {
114	            $integration->mergeProviderMetadata($metadataMerge);
115	        }
116	
117	        return [
118	            'updated' => $updated,
119	            'preserved' => $preserved,
120	        ];
121	    }
122	
123	    private function fillProfessional(Professional $professional, array $shopData): void
124	    {
125	        $professional->display_name = $this->str($shopData, 'name') ?: $professional->display_name;
126	        $professional->first_name = $this->str($shopData, 'name') ?: $professional->first_name;
127	        $professional->primary_email = $this->str($shopData, 'email') ?: $professional->primary_email;
128	        $professional->phone = $this->str($shopData, 'phone') ?: $professional->phone;
129	
130	        $professional->location_street_address = $this->str($shopData, 'address1') ?: $professional->location_street_address;
131	        $professional->location_city = $this->str($shopData, 'city') ?: $professional->location_city;
132	        $professional->location_state = $this->str($shopData, 'province') ?: $professional->location_state;
133	        $professional->location_postcode = $this->str($shopData, 'zip') ?: $professional->location_postcode;
134	        $professional->location_country = $this->str($shopData, 'country_name') ?: $professional->location_country;
135	        $professional->country_code = $this->str($shopData, 'country_code') ?: $professional->country_code;
136	        $professional->timezone = $this->str($shopData, 'iana_timezone') ?: $professional->timezone;
137	    }
138	
139	    private function fillBrandProfile(?BrandProfile $brandProfile, array $shopData): void
140	    {
141	        if ($brandProfile === null) {
142	            return;
143	        }
144	
145	        $domain = $this->str($shopData, 'domain');
146	        if ($domain !== '' && ($brandProfile->business_website === null || $brandProfile->business_website === '')) {
147	            $brandProfile->business_website = $domain;
148	        }
149	    }
150	
151	    private function fillIntegrationCurrency(?ProfessionalIntegration $integration, array $shopData): void
152	    {
153	        if ($integration === null) {
154	            return;
155	        }
156	
157	        $currency = strtoupper($this->str($shopData, 'currency'));
158	        if ($currency === '') {
159	            return;
160	        }
161	
162	        $metadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
163	
164	        // Only set if not already recorded — same idempotency rule, but use atomic merge so we
165	        // don't clobber sibling keys written by concurrent onboarding jobs.
166	        if (($metadata['shop_currency'] ?? '') === '') {
167	            $integration->mergeProviderMetadata(['shop_currency' => $currency]);
168	        }
169	    }
170	
171	    /**
172	     * Normalize a Shopify shop field to its stored form.
173	     * Country code and currency are upper-cased; everything else is trimmed as-is.
174	     */
175	    private function freshValueForField(array $field, array $shopData): string
176	    {
177	        $raw = $this->str($shopData, $field['shopify']);
178	
179	        if (in_array($field['shopify'], ['currency', 'country_code'], true)) {
180	            return strtoupper($raw);
181	        }
182	
183	        return $raw;
184	    }
185	
186	    /**
187	     * Apply a non-empty fresh Shopify value to the correct target + mark the dirty flag
188	     * for batched save. For integration-target fields (currently just shop_currency),
189	     * the value is added to $metadataMerge which the caller passes to mergeProviderMetadata().
190	     */
191	    private function applyFreshValue(
192	        array $field,
193	        string $freshValue,
194	        Professional $professional,
195	        ?BrandProfile $brandProfile,
196	        array &$metadataMerge,
197	        bool &$professionalDirty,
198	        bool &$brandProfileDirty,
199	    ): void {
200	        if ($field['target'] === 'professional') {
201	            $professional->{$field['column']} = $freshValue;
202	            $professionalDirty = true;
203	
204	            return;
205	        }
206	
207	        if ($field['target'] === 'brand_profile') {
208	            if ($brandProfile === null) {
209	                return;
210	            }
211	            $brandProfile->{$field['column']} = $freshValue;
212	            $brandProfileDirty = true;
213	
214	            return;
215	        }
216	
217	        $metadataMerge[$field['column']] = $freshValue;
218	    }
219	
220	    private function str(array $data, string $key): string
221	    {
222	        $value = Arr::get($data, $key);
223	
224	        return is_string($value) ? trim($value) : '';
225	    }
226	}
