11	use Illuminate\Contracts\Queue\ShouldQueue;
12	use Illuminate\Foundation\Bus\Dispatchable;
13	use Illuminate\Queue\InteractsWithQueue;
14	use Illuminate\Queue\SerializesModels;
15	use Illuminate\Support\Facades\Cache;
16	use Illuminate\Support\Facades\Log;
17	
18	// Processes shop/update webhooks — re-syncs brand profile fields and triggers
19	// a throttled brand-design refresh (logos, colours, enums, slogan).
20	class ProcessShopifyShopUpdateJob implements ShouldQueue
21	{
22	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
23	
24	    public int $tries = 3;
25	
26	    public int $timeout = 30;
27	
28	    public function __construct(
29	        public string $professionalId,
30	        public array $payload,
31	    ) {
32	        $this->onQueue('integrations');
33	    }
34	
35	    public function handle(): void
36	    {
37	        $professional = Professional::find($this->professionalId);
38	
39	        if (! $professional) {
40	            return;
41	        }
42	
43	        $site = Site::where('professional_id', $this->professionalId)->first();
44	
45	        if (! $site) {
46	            return;
47	        }
48	
49	        $brandProfile = BrandProfile::where('professional_id', $this->professionalId)->first();
50	        $integration = ProfessionalIntegration::query()
51	            ->where('professional_id', $this->professionalId)
52	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
53	            ->first();
54	
55	        // Re-sync profile fields from the shop/update payload (which is the shop object)
56	        app(ShopProfileAutoFillService::class)->fillFromShopData(
57	            $professional,
58	            $site,
59	            $brandProfile,
60	            $this->payload,
61	            $integration,
62	        );
63	
64	        // Re-sync the full brand-design shape (logos, colours, enums, slogan).
65	        // Throttled to once per hour per integration so a chatty shop/update
66	        // webhook stream can't pummel Shopify with brand-design fetches.
67	        if ($integration) {
68	            $cacheKey = "shopify:brand_design_sync:{$integration->id}";
69	            if (Cache::add($cacheKey, true, now()->addHour())) {
70	                SyncShopifyBrandDesignJob::dispatch((string) $integration->id);
71	            }
72	        }
73	
74	        Log::info('Shopify shop/update processed.', [
75	            'professional_id' => $this->professionalId,
76	            'shop_name' => $this->payload['name'] ?? null,
77	        ]);
78	    }
79	}
