3	namespace App\Http\Controllers\Api\Professional\Store;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\ResolveCurrentProfessional;
7	use App\Http\Resources\ShopifyResyncResource;
8	use App\Models\Core\Professional\ProfessionalIntegration;
9	use App\Services\Shopify\ShopifyDataResyncService;
10	use Illuminate\Http\JsonResponse;
11	use Illuminate\Http\Request;
12	use Illuminate\Support\Facades\RateLimiter;
13	use RuntimeException;
14	
15	// V2: Brand "Resync from Shopify" trigger. Refreshes profile/brand fields + logo + theme tokens.
16	//     Rate-limited to once per 60s per integration so users cannot flood Shopify's API.
17	class ShopifyResyncController extends ApiController
18	{
19	    use ResolveCurrentProfessional;
20	
21	    public function __construct(
22	        private readonly ShopifyDataResyncService $resyncService,
23	    ) {}
24	
25	    public function __invoke(Request $request): JsonResponse
26	    {
27	        $pro = $this->currentProfessional($request);
28	
29	        // Scope strictly by the authenticated professional — never accept an integration id
30	        // from the request body; that would let a brand touch another brand's integration.
31	        $integration = ProfessionalIntegration::query()
32	            ->where('professional_id', $pro->id)
33	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
34	            ->first();
35	
36	        if (! $integration) {
37	            return $this->error('No Shopify integration found for this brand.', 404);
38	        }
39	
40	        if (trim((string) $integration->access_token) === '') {
41	            return $this->error('Your Shopify store is not fully connected.', 409);
42	        }
43	
44	        $rateLimitKey = "shopify-resync:{$integration->id}";
45	        if (RateLimiter::tooManyAttempts($rateLimitKey, 1)) {
46	            $retryAfter = RateLimiter::availableIn($rateLimitKey);
47	
48	            return $this->error(
49	                'Shopify resync is rate-limited. Try again shortly.',
50	                429,
51	            )->header('Retry-After', (string) $retryAfter);
52	        }
53	        RateLimiter::hit($rateLimitKey, 60);
54	
55	        try {
56	            $result = $this->resyncService->resync($integration);
57	        } catch (RuntimeException $e) {
58	            return $this->error('Unable to resync from Shopify: '.$e->getMessage(), 502);
59	        }
60	
61	        // Resolve the resource to a plain array so the response is un-wrapped (no "data" envelope).
62	        return $this->success((new ShopifyResyncResource($result))->resolve($request));
63	    }
64	}
