3	namespace App\Services\Shopify;
4	
5	use App\Jobs\Shopify\SyncShopifyBrandDesignJob;
6	use App\Models\Core\Professional\ProfessionalIntegration;
7	use App\Services\Shopify\Client\ShopifyAdminClient;
8	use Illuminate\Support\Arr;
9	use Illuminate\Support\Facades\DB;
10	use Illuminate\Support\Facades\Log;
11	use RuntimeException;
12	
13	// V2: On-demand Shopify data refresh. Pulls fresh shop.json, diff-merges profile/brand fields via
14	//     ShopProfileAutoFillService::resyncFromShopData (preserving user edits), and re-dispatches the
15	//     unified brand-design sync job. Used by the Brand "Resync from Shopify" button in settings.
16	class ShopifyDataResyncService
17	{
18	    public function __construct(
19	        private readonly ShopProfileAutoFillService $autoFill,
20	        private readonly ShopifyAdminClient $client,
21	    ) {}
22	
23	    /**
24	     * @return array{
25	     *   fields_updated: string[],
26	     *   fields_preserved: string[],
27	     *   jobs_dispatched: string[],
28	     *   last_resynced_at: string,
29	     * }
30	     */
31	    public function resync(ProfessionalIntegration $integration): array
32	    {
33	        $metadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
34	        $shopDomain = trim((string) Arr::get($metadata, 'shop_domain', ''));
35	        $accessToken = trim((string) $integration->access_token);
36	
37	        if ($shopDomain === '' || $accessToken === '' || ! preg_match('/^[a-z0-9\-]+\.myshopify\.com$/', $shopDomain)) {
38	            throw new RuntimeException('Shopify integration is missing a valid shop domain or access token.');
39	        }
40	
41	        // Fetch BEFORE the transaction — Shopify Admin API calls take ~200ms and would hold
42	        // row locks on professionals / brand_profiles / integrations the whole time if inside.
43	        $shopData = $this->fetchShopData($shopDomain, $accessToken);
44	
45	        $integrationId = (string) $integration->id;
46	        $lastResyncedAt = now()->toIso8601String();
47	
48	        // Post-API writes go in one transaction so partial failures roll back cleanly:
49	        //   - diff-merge into Professional / BrandProfile / ProfessionalIntegration
50	        //   - last_resynced_at stamp on integration metadata
51	        //   - unified brand-design job dispatch (Laravel queues defer until commit inside txn)
52	        $diff = DB::connection('pgsql')->transaction(function () use ($integration, $integrationId, $shopData, $lastResyncedAt) {
53	            $diff = $this->autoFill->resyncFromShopData($integration, $shopData);
54	
55	            // Atomic merge so sibling keys (webhook_ids, storefront_access_token, etc.) survive.
56	            $integration->mergeProviderMetadata(['last_resynced_at' => $lastResyncedAt]);
57	
58	            // Dispatched inside the transaction on purpose — queues hold them until commit,
59	            // so a rollback prevents an orphaned brand-design job from firing.
60	            SyncShopifyBrandDesignJob::dispatch($integrationId);
61	
62	            return $diff;
63	        });
64	
65	        Log::info('Shopify data resync completed.', [
66	            'integration_id' => $integrationId,
67	            'shop_domain' => $shopDomain,
68	            'updated_count' => count($diff['updated']),
69	            'preserved_count' => count($diff['preserved']),
70	        ]);
71	
72	        return [
73	            'fields_updated' => $diff['updated'],
74	            'fields_preserved' => $diff['preserved'],
75	            'jobs_dispatched' => ['brand_design'],
76	            'last_resynced_at' => $lastResyncedAt,
77	        ];
78	    }
79	
80	    /**
81	     * Fetch the shop.json payload from the Shopify Admin REST API.
82	     * Thrown RuntimeException is caught by the controller and surfaced as a 502/503.
83	     */
84	    private function fetchShopData(string $shopDomain, string $accessToken): array
85	    {
86	        $apiVersion = trim((string) config('services.shopify.api_version', '2025-01'));
87	
88	        try {
89	            $response = $this->client->rest(
90	                method: 'GET',
91	                shopDomain: $shopDomain,
92	                accessToken: $accessToken,
93	                path: "/admin/api/{$apiVersion}/shop.json",
94	            );
95	        } catch (\App\Exceptions\Shopify\ShopifyTransportException $e) {
96	            throw new RuntimeException('Unable to reach Shopify: '.$e->getMessage(), previous: $e);
97	        }
98	
99	        $shop = $response->json('shop');
100	
101	        if (! is_array($shop)) {
102	            throw new RuntimeException('Shopify returned an empty or malformed shop payload.');
103	        }
104	
105	        return $shop;
106	    }
107	}
