17	// Processes shop/update webhooks — re-syncs brand profile fields (honouring any
18	// shopify_sync_locked_fields the brand has set) and triggers a throttled brand-design
19	// refresh (logos, colours, enums, slogan).
20	class ProcessShopifyShopUpdateJob implements ShouldQueue
21	{
22	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
23	
24	    public int $tries = 3;
25	
26	    public int $timeout = 30;
27	
28	    public function __construct(
29	        public string $professionalId,
30	        public array $payload,
31	    ) {
32	        $this->onQueue('integrations');
33	    }
34	
35	    public function handle(): void
36	    {
37	        $professional = Professional::find($this->professionalId);
38	
39	        if (! $professional) {
40	            return;
41	        }
42	
43	        $site = Site::where('professional_id', $this->professionalId)->first();
44	
45	        if (! $site) {
46	            return;
47	        }
48	
49	        $integration = ProfessionalIntegration::query()
50	            ->where('professional_id', $this->professionalId)
51	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
52	            ->first();
53	
54	        if (! $integration) {
55	            Log::warning('Shopify shop/update: no integration record found.', [
56	                'professional_id' => $this->professionalId,
57	            ]);
58	
59	            return;
60	        }
61	
62	        // Re-sync profile fields, honouring shopify_sync_locked_fields for brands
63	        // that have customized specific fields locally.
