65	            $integration,
66	            $this->payload,
67	        );
68	
69	        // Re-sync the full brand-design shape (logos, colours, enums, slogan).
70	        // Throttled to once per hour per integration so a chatty shop/update
71	        // webhook stream can't pummel Shopify with brand-design fetches.
72	        $cacheKey = "shopify:brand_design_sync:{$integration->id}";
73	        if (Cache::add($cacheKey, true, now()->addHour())) {
